-- SimsCraft 3.0: перенос купленной мебели со старых номеров на новые (выполнять в acore_world)
SET NAMES utf8mb4;
DROP TEMPORARY TABLE IF EXISTS `sc_map`;
CREATE TEMPORARY TABLE `sc_map` (`old` INT UNSIGNED PRIMARY KEY, `new` INT UNSIGNED NOT NULL, `refund` INT UNSIGNED NOT NULL);
INSERT INTO `sc_map` VALUES (190200,600002,0),(190201,600027,0),(190202,600056,0),(190203,600058,0),(190204,600087,0),(190205,600035,0),(190206,600142,0),(190207,600060,0),(190208,600000,0),(190209,600004,0),(190210,600003,0),(190211,600008,0),(190212,600010,0),(190213,600016,0),(190214,600017,0),(190215,600018,0),(190216,600019,0),(190217,600015,0),(190218,600028,0),(190219,0,100000),(190220,0,100000),(190221,600038,0),(190222,600043,0),(190223,600034,0),(190224,0,100000),(190225,600032,0),(190226,0,100000),(190227,0,100000),(190228,0,100000),(190229,600047,0),(190230,600051,0),(190231,600052,0),(190232,0,100000),(190233,0,100000),(190234,600061,0),(190235,600064,0),(190236,600060,0),(190237,600068,0),(190238,0,100000),(190239,600079,0),(190240,600081,0),(190241,600083,0),(190242,600084,0),(190243,600086,0),(190244,0,100000),(190245,600076,0),(190246,0,100000),(190247,600090,0),(190248,0,100000),(190249,0,100000),(190250,600096,0),(190251,0,100000),(190252,600103,0),(190253,600104,0),(190254,600105,0),(190255,600106,0),(190256,600107,0),(190257,600108,0),(190258,0,100000),(190259,0,100000),(190260,0,100000);
UPDATE acore_characters.character_sims_furniture f JOIN `gameobject` g ON g.`id` = f.`entry` AND g.`map` = f.`map` AND ABS(g.`position_x` - f.`x`) < 1 AND ABS(g.`position_y` - f.`y`) < 1 SET f.`spawn` = g.`guid` WHERE f.`spawn` = 0 AND f.`entry` BETWEEN 190200 AND 190599;
DELETE g FROM `gameobject` g JOIN acore_characters.character_sims_furniture f ON g.`guid` = f.`spawn` JOIN `sc_map` m ON m.`old` = f.`entry` WHERE m.`new` = 0 AND f.`spawn` > 0;
UPDATE `gameobject` g JOIN acore_characters.character_sims_furniture f ON g.`guid` = f.`spawn` JOIN `sc_map` m ON m.`old` = f.`entry` SET g.`id` = m.`new` WHERE m.`new` > 0 AND f.`spawn` > 0;
UPDATE acore_characters.character_sims_furniture f JOIN `sc_map` m ON m.`old` = f.`entry` SET f.`refund` = m.`refund`, f.`entry` = IF(m.`new` = 0, f.`entry`, m.`new`);
UPDATE acore_characters.character_sims_furniture SET `refund` = 100000 WHERE `entry` BETWEEN 190200 AND 190599 AND `refund` = 0;
DROP TEMPORARY TABLE `sc_map`;
